import { Avatar, Card, CardHeader } from "@heroui/react";
import { Image } from "antd";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast, ToastContainer } from "react-toastify";

export default function WholesalersCarousel({
  wholesalers,
  selectedWholesaler,
  setselectedWholesaler,
}) {
  const navigate = useNavigate();

  const handleClick = (item) => {
    toast.success(item.title);
    console.log("WSSS", item);
    setselectedWholesaler(item);
    navigate(`/marketplace/wholesaler/cart/${item.id}`, {
      state: {
        id: item.id,
        title: item.title,
      },
    });
  };

  return (
    <div className="w-full">
      <ToastContainer theme="colored" />
      <div class="relative flex overflow-x-hidden ">
        <div class="animate-marquee whitespace-nowrap flex cursor-pointer ">
          {wholesalers.map((item) => {
            return (
              <Card isPressable
                className="shadow-md rounded-md"
                onPress={() => handleClick(item)}
              >

                <CardHeader className="justify-between">

                  <Avatar isBordered
                    radius="full"
                    size="lg"
                    src="https://heroui.com/avatars/avatar-1.png" />

                  <div className="flex flex-col gap-1 items-start justify-center">
                    <h4 className="text-small font-semibold leading-none text-default-600">{item.title}</h4>
                    <h5 className="text-small tracking-tight text-default-400">@zoeylang</h5>
                  </div>
                </CardHeader>

              </Card>
            );
          })}
        </div>
      </div>
    </div>
  );
}
